-- Tecno-Store · esquema de base de datos (ejecutar en Supabase > SQL Editor)
create table if not exists categorias (
  id bigint generated by default as identity primary key,
  nombre text not null unique
);
create table if not exists productos (
  id uuid primary key default gen_random_uuid(),
  codigo bigint generated by default as identity unique,
  nombre text not null,
  categoria_id bigint references categorias(id) on delete restrict,
  marca text,
  descripcion text,
  precio numeric(12,2) not null check (precio >= 0),
  stock integer not null default 0 check (stock >= 0),
  imagenes text[] not null default '{}',
  especificaciones jsonb not null default '{}',
  activo boolean not null default true,
  creado timestamptz not null default now()
);
alter table categorias enable row level security;
alter table productos enable row level security;
-- Público: ve categorías y productos activos. Administrador (autenticado): todo.
create policy cat_lectura on categorias for select using (true);
create policy cat_admin on categorias for all to authenticated using (true) with check (true);
create policy prod_lectura on productos for select using (activo);
create policy prod_admin on productos for all to authenticated using (true) with check (true);

